PRAGMA foreign_keys = ON;
CREATE TABLE markets (mint TEXT PRIMARY KEY, creator TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('curve','complete','pool')), launched_at INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX markets_created ON markets(launched_at DESC);
CREATE INDEX markets_creator ON markets(creator);
CREATE TABLE trades (id TEXT PRIMARY KEY, mint TEXT NOT NULL REFERENCES markets(mint), trader TEXT NOT NULL, slot INTEGER NOT NULL, time INTEGER NOT NULL, signature TEXT NOT NULL, gross_sol TEXT NOT NULL, usd_micros TEXT, excluded INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX trades_market_time ON trades(mint,time DESC);
CREATE INDEX trades_trader ON trades(trader,time DESC);
CREATE TABLE commitments (id TEXT PRIMARY KEY, mint TEXT NOT NULL REFERENCES markets(mint), owner TEXT NOT NULL, start_at INTEGER NOT NULL, unlock_at INTEGER NOT NULL, withdrawn INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX commitments_owner ON commitments(owner,unlock_at);
CREATE TABLE ownership (mint TEXT NOT NULL, wallet TEXT NOT NULL, balance TEXT NOT NULL, lots TEXT NOT NULL CHECK(json_valid(lots)), updated_at INTEGER NOT NULL, PRIMARY KEY(mint,wallet));
CREATE TABLE token_accounts (address TEXT PRIMARY KEY, mint TEXT NOT NULL, owner TEXT NOT NULL, beneficiary TEXT);
CREATE TABLE holder_weights (epoch INTEGER NOT NULL, mint TEXT NOT NULL, wallet TEXT NOT NULL, weight TEXT NOT NULL, PRIMARY KEY(epoch,mint,wallet));
CREATE TABLE holding_checkpoints (mint TEXT PRIMARY KEY, at INTEGER NOT NULL, completed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE holding_rewards (epoch INTEGER NOT NULL, mint TEXT NOT NULL, wallet TEXT NOT NULL, weight TEXT NOT NULL, PRIMARY KEY(epoch,mint,wallet));
CREATE TABLE fee_deposits (id TEXT PRIMARY KEY, mint TEXT NOT NULL, owner TEXT NOT NULL, amount TEXT NOT NULL, start_at INTEGER NOT NULL, unlock_at INTEGER NOT NULL);
CREATE TABLE oracle_prices (at INTEGER PRIMARY KEY, publish_time INTEGER NOT NULL, usd_micros TEXT NOT NULL, r2_key TEXT NOT NULL);
CREATE TABLE indexed_events (id TEXT PRIMARY KEY, slot INTEGER NOT NULL);
CREATE TABLE checkpoints (id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE pending_blocks (slot INTEGER PRIMARY KEY, parent INTEGER NOT NULL, time INTEGER NOT NULL, object_key TEXT NOT NULL, hash TEXT NOT NULL, applied INTEGER NOT NULL DEFAULT 0);
CREATE TABLE outbox (sequence INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, mint TEXT, wallet TEXT, data TEXT NOT NULL CHECK(json_valid(data)), published INTEGER NOT NULL DEFAULT 0);
CREATE INDEX outbox_pending ON outbox(published,sequence);
CREATE TABLE epochs (epoch INTEGER PRIMARY KEY, status TEXT NOT NULL, pool_sol TEXT NOT NULL, pool_usd TEXT, snapshot_hash TEXT, snapshot_key TEXT, beacon_after INTEGER, drand_round INTEGER, data TEXT CHECK(data IS NULL OR json_valid(data)));
CREATE TABLE tickets (epoch INTEGER NOT NULL, wallet TEXT NOT NULL, trading INTEGER NOT NULL CHECK(trading BETWEEN 0 AND 1000), holding INTEGER NOT NULL CHECK(holding BETWEEN 0 AND 1000), creator INTEGER NOT NULL CHECK(creator BETWEEN 0 AND 1000), PRIMARY KEY(epoch,wallet));
CREATE TABLE distributions (id TEXT PRIMARY KEY, epoch INTEGER NOT NULL, kind TEXT NOT NULL, mint TEXT NOT NULL, amount TEXT NOT NULL, status TEXT NOT NULL, root TEXT, snapshot_hash TEXT, snapshot_key TEXT, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE claims (id TEXT PRIMARY KEY, distribution TEXT NOT NULL REFERENCES distributions(id), epoch INTEGER NOT NULL, mint TEXT NOT NULL, kind TEXT NOT NULL, wallet TEXT NOT NULL, amount TEXT NOT NULL, proof TEXT NOT NULL CHECK(json_valid(proof)), claimed INTEGER NOT NULL DEFAULT 0, UNIQUE(distribution,wallet));
CREATE INDEX claims_wallet ON claims(wallet,epoch DESC);
CREATE TABLE transactions (id TEXT PRIMARY KEY, signature TEXT NOT NULL, raw TEXT NOT NULL, last_valid_height INTEGER NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE protocol_actions (id TEXT PRIMARY KEY, kind TEXT NOT NULL, mint TEXT, amount TEXT NOT NULL, time INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE upload_nonces (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
